package io.github.coyotewolf.dragonbalance;

import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.minecraftforge.common.ForgeConfigSpec;

public final class PatchConfig {
    public static final Map<String, Double> DEFAULT_HEALTH;
    public static final Set<String> FLYING;
    public static final List<String> DEFAULT_PROTECTED;
    public static final ForgeConfigSpec SPEC;
    public static final ForgeConfigSpec.BooleanValue ENABLE_HEALTH;
    public static final ForgeConfigSpec.BooleanValue FIRE_IMMUNITY;
    public static final ForgeConfigSpec.BooleanValue SELF_IMMUNITY;
    public static final ForgeConfigSpec.BooleanValue ULTIMATE_PENALTY;
    public static final ForgeConfigSpec.BooleanValue TEAM_PROTECTION;
    public static final ForgeConfigSpec.BooleanValue VANILLA_TEAMS;
    public static final ForgeConfigSpec.BooleanValue FTB_TEAMS;
    public static final ForgeConfigSpec.BooleanValue BETTER_PARTY;
    public static final ForgeConfigSpec.DoubleValue BABY_SCALE;
    public static final ForgeConfigSpec.IntValue HEALTH_PRESET_REVISION;
    public static final ForgeConfigSpec.BooleanValue SCALE_TAMING_STUN;
    public static final ForgeConfigSpec.ConfigValue<List<? extends String>> PROTECTED;
    public static final Map<String, ForgeConfigSpec.DoubleValue> HEALTH;

    public static boolean protectedSpecies(String id) {
        return ((List)PROTECTED.get()).contains(id);
    }

    public static boolean preventUltimatePenalty() {
        return (Boolean)SELF_IMMUNITY.get() != false && (Boolean)ULTIMATE_PENALTY.get() != false && PatchConfig.protectedSpecies("saintsdragons:ignivorus");
    }

    private PatchConfig() {
    }

    static {
        DEFAULT_PROTECTED = List.of("dragonsofberk:night_fury", "dragonsofberk:light_fury", "dragonsofberk:night_light", "saintsdragons:cindervane", "saintsdragons:ignivorus");
        HEALTH = new LinkedHashMap<String, ForgeConfigSpec.DoubleValue>();
        LinkedHashMap<String, Double> h = new LinkedHashMap<String, Double>();
        h.put("dragonsofberk:terrible_terror", 450.0);
        h.put("dragonsofberk:deadly_nadder", 720.0);
        h.put("dragonsofberk:gronckle", 780.0);
        h.put("dragonsofberk:light_fury", 780.0);
        h.put("dragonsofberk:night_light", 840.0);
        h.put("dragonsofberk:night_fury", 960.0);
        h.put("dragonsofberk:skrill", 960.0);
        h.put("dragonsofberk:zippleback", 900.0);
        h.put("dragonsofberk:monstrous_nightmare", 1020.0);
        h.put("dragonsofberk:triple_stryke", 1080.0);
        h.put("dragonsofberk:speed_stinger", 240.0);
        h.put("dragonsofberk:speed_stinger_leader", 360.0);
        h.put("dragonsofberk:stinger", 540.0);
        h.put("saintsdragons:nulljaw", 540.0);
        h.put("saintsdragons:cindervane", 720.0);
        h.put("saintsdragons:volitans", 900.0);
        h.put("saintsdragons:raevyx", 1080.0);
        h.put("saintsdragons:ignivorus", 2100.0);
        h.put("saintsdragons:stegonaut", 720.0);
        h.put("saintsdragons:varasuchus", 1080.0);
        h.put("saintsdragons:atroxiia", 1200.0);
        DEFAULT_HEALTH = Collections.unmodifiableMap(h);
        HashSet f = new HashSet(h.keySet());
        f.removeAll(List.of("dragonsofberk:speed_stinger", "dragonsofberk:speed_stinger_leader", "dragonsofberk:stinger", "saintsdragons:stegonaut", "saintsdragons:varasuchus", "saintsdragons:atroxiia"));
        FLYING = Set.copyOf(f);
        ForgeConfigSpec.Builder b = new ForgeConfigSpec.Builder();
        b.comment("Server-authoritative only. Restart the server after editing. HP units, not hearts.").push("general");
        HEALTH_PRESET_REVISION = b.comment("Managed preset migration marker; do not edit.").defineInRange("healthPresetRevision", 0, 0, 2);
        SCALE_TAMING_STUN = b.comment("Scale Saints taming stun HP by balanced maximum / configured original maximum.").define("scaleTamingStunHealth", true);
        ENABLE_HEALTH = b.define("enableHealthBalance", true);
        BABY_SCALE = b.comment("Baby target = adult target * scale. Flying dragon species have a 150 HP floor, including babies.").defineInRange("babyHealthScale", 0.5, 0.1, 1.0);
        FIRE_IMMUNITY = b.comment("Cancel damage tagged minecraft:is_fire (fire, burning, lava, hot floor) for protected species.").define("fireImmunity", true);
        SELF_IMMUNITY = b.comment("Cancel only attacks attributed to the victim itself; attacks by other dragons still work.").define("selfAttackImmunity", true);
        ULTIMATE_PENALTY = b.comment("Prevent Ignivorus ultimate from directly reducing its health to 50. Requires selfAttackImmunity and protected Ignivorus.").define("preventIgnivorusUltimatePenalty", true);
        PROTECTED = b.defineListAllowEmpty(List.of("protectedSpecies"), () -> DEFAULT_PROTECTED, x -> {
            String s;
            return x instanceof String && h.containsKey(s = (String)x);
        });
        TEAM_PROTECTION = b.comment("Protect all supported tamed dragons from attacks attributed to their owner or that owner's teammates.").define("teamFriendlyFireProtection", true);
        VANILLA_TEAMS = b.define("useVanillaTeams", true);
        FTB_TEAMS = b.define("useFtbTeams", true);
        BETTER_PARTY = b.comment("Optional independent Better Party membership; not the same as FTB Teams.").define("useBetterParty", false);
        b.pop().push("health");
        h.forEach((id, hp) -> HEALTH.put((String)id, b.comment("Adult HP floor for " + id + "; existing higher base HP is preserved.").defineInRange(id.replace(':', '_'), hp.doubleValue(), 1.0, 65536.0)));
        b.pop();
        SPEC = b.build();
    }
}

